INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (1, 1, 'funcoes-1-e-2-grau', 1, 'Funções (1º e 2º grau)', 'Estudo de gráficos, raízes e vértices de parábolas.', 'Reconhecer funções do 1º e do 2º grau, interpretar seus coeficientes, calcular raízes e encontrar o vértice da parábola.', 1, 'funcoes (1º e 2º grau) estudo de graficos, raizes e vertices de parabolas. reconhecer funcoes do 1º e do 2º grau, interpretar seus coeficientes, calcular raizes e encontrar o vertice da parabola. o que e uma funcao uma funcao e uma regra que associa cada valor de entrada x a um unico valor de saida y = f(x). no dia a dia, o preco de uma corrida que depende da distancia ou a altura de uma bola que depende do tempo sao exemplos de funcoes. na funcao do 1º grau, a variavel x aparece com expoente 1 e o grafico e uma reta: a saida cresce ou diminui sempre no mesmo ritmo. na funcao do 2º grau, aparece o termo x2 e o grafico e uma curva chamada parabola. ela tem um ponto especial, o vertice, onde a funcao atinge seu valor minimo ou maximo. as raizes (ou zeros) de uma funcao sao os valores de x em que f(x) = 0. no grafico, sao os pontos em que a curva toca o eixo x. conceitos e formulas funcao do 1º grau - forma: f(x) = ax + b, com a = 0. - a e a taxa de variacao: se a > 0, a funcao e crescente; se a < 0, e decrescente. - b e o valor de f(0): a reta corta o eixo y no ponto (0, b). - raiz: x = −b/a (so existe divisao porque a = 0). funcao do 2º grau - forma: f(x) = ax2 + bx + c, com a = 0. - se a > 0, a parabola tem concavidade para cima e o vertice e o ponto de minimo; se a < 0, concavidade para baixo e o vertice e o ponto de maximo. - discriminante: δ = b2 − 4ac. se δ > 0, ha duas raizes reais diferentes; se δ = 0, uma raiz real (dupla); se δ < 0, nenhuma raiz real. - formula de bhaskara: x = (−b ± √δ) / (2a), usada apenas quando δ ≥ 0. - vertice: xv = −b/(2a) e yv = −δ/(4a), ou yv = f(xv). exemplo 1 — preco de uma corrida (1º grau) uma corrida de aplicativo custa r$ 5,00 fixos mais r$ 2,00 por quilometro. qual e o preco de uma corrida de 8 km? e quantos quilometros e possivel rodar com r$ 29,00? 1. o valor fixo e b = 5 e o valor por quilometro e a = 2. entao c(x) = 2x + 5. 2. para 8 km: c(8) = 2·8 + 5 = 16 + 5 = 21. a corrida custa r$ 21,00. 3. para r$ 29,00: 2x + 5 = 29 → 2x = 24 → x = 12. e possivel rodar 12 km. 4. como a = 2 > 0, a funcao e crescente: quanto maior a distancia, maior o preco. exemplo 2 — raizes e vertice (2º grau) vamos analisar f(x) = x2 − 6x + 8. 1. coeficientes: a = 1, b = −6 e c = 8. 2. discriminante: δ = (−6)2 − 4·1·8 = 36 − 32 = 4. como δ > 0, ha duas raizes reais. 3. raizes: x = (6 ± √4) / 2 = (6 ± 2) / 2, entao x = 4 ou x = 2. 4. vertice: xv = 6/2 = 3 e yv = f(3) = 9 − 18 + 8 = −1. logo, v = (3, −1). 5. como a = 1 > 0, a concavidade e para cima e o vertice e o ponto de minimo. exemplo 3 — altura maxima de uma bola (2º grau) a altura de uma bola, em metros, t segundos apos o chute e h(t) = −5t2 + 20t. qual e a altura maxima? 1. como a = −5 < 0, a parabola tem concavidade para baixo e o vertice e o ponto de maximo. 2. instante do maximo: tv = −20/(2·(−5)) = 2 segundos. 3. altura maxima: h(2) = −5·4 + 20·2 = −20 + 40 = 20 metros. resumo - 1º grau: f(x) = ax + b, grafico reta; raiz x = −b/a; o sinal de a indica se cresce ou decresce. - 2º grau: f(x) = ax2 + bx + c, grafico parabola; o sinal de a indica a concavidade. - δ = b2 − 4ac decide quantas raizes reais existem. - o vertice (xv, yv) da o valor minimo (a > 0) ou maximo (a < 0) da funcao.');
INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (2, 1, 'progressoes-pa-e-pg', 1, 'Progressões (PA e PG)', 'Sequências numéricas que crescem ou diminuem de forma constante ou multiplicativa.', 'Identificar progressões aritméticas e geométricas, calcular a razão, um termo qualquer e a soma dos primeiros termos.', 2, 'progressoes (pa e pg) sequencias numericas que crescem ou diminuem de forma constante ou multiplicativa. identificar progressoes aritmeticas e geometricas, calcular a razao, um termo qualquer e a soma dos primeiros termos. sequencias com padrao uma progressao e uma sequencia de numeros que segue uma regra fixa. na progressao aritmetica (pa), cada termo e obtido somando sempre o mesmo valor ao anterior. esse valor e a razao r. exemplo: (3, 7, 11, 15, ...) tem r = 4. aparece em situacoes como economizar um valor que aumenta a mesma quantia todo mes. na progressao geometrica (pg), cada termo e obtido multiplicando sempre pelo mesmo valor. esse valor e a razao q. exemplo: (2, 6, 18, 54, ...) tem q = 3. aparece em crescimentos que dobram ou triplicam, como a multiplicacao de bacterias. para descobrir o tipo: se a diferenca entre termos vizinhos e constante, e pa; se a divisao entre termos vizinhos e constante, e pg. conceitos e formulas progressao aritmetica (n e a posicao do termo, inteiro e n ≥ 1) - razao: r = a2 − a1. - termo geral: an = a1 + (n − 1)·r. - soma dos n primeiros termos: sn = (a1 + an)·n / 2. progressao geometrica (a1 = 0) - razao: q = a2 / a1. - termo geral: an = a1·qn − 1. - soma dos n primeiros termos: sn = a1·(qn − 1) / (q − 1), valida para q = 1. se q = 1, todos os termos sao iguais e sn = n·a1. exemplo 1 — economia mensal (pa) uma pessoa guarda r$ 50,00 no primeiro mes e, a cada mes, guarda r$ 10,00 a mais do que no mes anterior. quanto ela guarda no 12º mes? e quanto tera guardado ao todo em 12 meses? 1. os valores formam uma pa com a1 = 50 e r = 10. 2. 12º termo: a12 = 50 + (12 − 1)·10 = 50 + 110 = 160. no 12º mes ela guarda r$ 160,00. 3. soma: s12 = (50 + 160)·12 / 2 = 210·6 = 1260. ao todo, r$ 1.260,00. exemplo 2 — crescimento de bacterias (pg) uma cultura comeca com 300 bacterias e a quantidade dobra a cada hora. quantas bacterias havera ao final de 5 horas? 1. a sequencia (300, 600, 1200, ...) e uma pg com a1 = 300 (inicio) e q = 2. 2. o inicio e o 1º termo; ao final de 5 horas estamos no 6º termo. 3. a6 = 300·25 = 300·32 = 9600. havera 9.600 bacterias. exemplo 3 — soma de uma pg qual e a soma dos 5 primeiros termos da pg (2, 6, 18, ...)? 1. a1 = 2 e q = 6/2 = 3 (q = 1, entao a formula da soma pode ser usada). 2. s5 = 2·(35 − 1) / (3 − 1) = 2·(243 − 1) / 2 = 242. 3. conferindo: 2 + 6 + 18 + 54 + 162 = 242. resumo - pa: soma-se a razao r; an = a1 + (n − 1)·r; sn = (a1 + an)·n / 2. - pg: multiplica-se pela razao q; an = a1·qn − 1; sn = a1·(qn − 1)/(q − 1), com q = 1. - atencao a posicao do termo: o primeiro termo e a1, nao a0.');
INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (3, 1, 'funcao-exponencial-e-logaritmos', 1, 'Função Exponencial e Logaritmos', 'Conceitos avançados de crescimento rápido e inversão de cálculos.', 'Resolver equações exponenciais simples, calcular logaritmos usando suas propriedades e aplicar ambos em situações de crescimento e decaimento.', 3, 'funcao exponencial e logaritmos conceitos avancados de crescimento rapido e inversao de calculos. resolver equacoes exponenciais simples, calcular logaritmos usando suas propriedades e aplicar ambos em situacoes de crescimento e decaimento. crescimento rapido e operacao inversa na funcao exponencial, a variavel esta no expoente: f(x) = 2x. a cada passo, o valor e multiplicado pela mesma base, por isso o crescimento (ou a queda) e muito rapido. ela descreve juros compostos, crescimento de populacoes e decaimento de substancias. o logaritmo responde a pergunta inversa: \"a que expoente devo elevar a base para obter este numero?\". como 23 = 8, dizemos que log2 8 = 3. logaritmos sao uteis quando a incognita esta no expoente e nao e possivel escrever os dois lados da equacao na mesma base. conceitos e formulas funcao exponencial - f(x) = ax, com a > 0 e a = 1. - se a > 1, a funcao e crescente; se 0 < a < 1, e decrescente. - o grafico passa por (0, 1) e f(x) > 0 para todo x real. - propriedades das potencias: am·an = am + n; am / an = am − n; (am)n = am·n; a0 = 1. - equacao exponencial: se a > 0 e a = 1, entao ax = ay quando, e somente quando, x = y. logaritmos - definicao: loga b = x significa ax = b, com a > 0, a = 1 e b > 0. - quando a base nao aparece, ela e 10: log 1000 = 3. - para m > 0 e n > 0: loga(m·n) = loga m + loga n; loga(m/n) = loga m − loga n; loga(mk) = k·loga m. - mudanca de base: loga b = log b / log a. exemplo 1 — equacao exponencial resolva 3x + 1 = 81. 1. escreva 81 como potencia de 3: 81 = 34. 2. a equacao fica 3x + 1 = 34. como as bases sao iguais (e validas), os expoentes sao iguais. 3. x + 1 = 4 → x = 3. 4. conferindo: 33 + 1 = 34 = 81. exemplo 2 — calculando logaritmos a) quanto vale log2 32? 1. procuramos x tal que 2x = 32. como 25 = 32, log2 32 = 5. b) sabendo que log 2 ≈ 0,301, quanto vale log 8? 1. 8 = 23, entao log 8 = log 23 = 3·log 2. 2. log 8 ≈ 3·0,301 = 0,903. exemplo 3 — quando a populacao dobra uma cidade tem 10.000 habitantes e cresce 10% ao ano, ou seja, p(t) = 10000·1,1t, com t em anos. em quanto tempo a populacao dobra? use log 2 ≈ 0,301 e log 1,1 ≈ 0,0414. 1. dobrar significa p(t) = 20000: 10000·1,1t = 20000 → 1,1t = 2. 2. nao da para escrever 2 como potencia de 1,1, entao aplicamos log nos dois lados: t·log 1,1 = log 2. 3. t = 0,301 / 0,0414 ≈ 7,3. a populacao dobra em pouco mais de 7 anos. resumo - exponencial: f(x) = ax, a > 0 e a = 1; cresce se a > 1 e decresce se 0 < a < 1. - mesma base dos dois lados → iguale os expoentes. - loga b = x ⇔ ax = b (a > 0, a = 1, b > 0). - produto vira soma, divisao vira subtracao e expoente \"desce\" multiplicando.');
INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (4, 1, 'geometria-espacial', 2, 'Geometria Espacial', 'Cálculo de volume e área de sólidos como cilindros, cones e esferas.', 'Calcular áreas e volumes de prismas, cilindros, cones e esferas, escolhendo a fórmula adequada e trabalhando com unidades de medida.', 1, 'geometria espacial calculo de volume e area de solidos como cilindros, cones e esferas. calcular areas e volumes de prismas, cilindros, cones e esferas, escolhendo a formula adequada e trabalhando com unidades de medida. medindo objetos em tres dimensoes a geometria espacial estuda solidos, como caixas, latas, casquinhas de sorvete e bolas. - a area mede a superficie que cobre o solido (quanto papel seria preciso para embrulha-lo). e dada em unidades quadradas, como cm2 e m2. - o volume mede o espaco ocupado (quanto cabe dentro). e dado em unidades cubicas, como cm3 e m3. prismas e cilindros tem duas bases iguais e paralelas: o volume e a area da base vezes a altura. o cone e como um cilindro que \"afina\" ate um ponto, e seu volume e um terco do cilindro de mesma base e altura. a esfera tem formulas proprias, que dependem so do raio. conceitos e formulas todas as medidas devem estar na mesma unidade antes de calcular. respostas podem deixar π indicado (ex.: 12π cm3) ou usar uma aproximacao, como π ≈ 3,14, quando o enunciado pedir. prismas (ab = area da base, h = altura) - volume: v = ab·h. - cubo de aresta a: v = a3; area total a = 6a2. - paralelepipedo de dimensoes a, b e c: v = a·b·c; area total a = 2(ab + ac + bc). cilindro (raio r, altura h) - area da base: ab = πr2. volume: v = πr2h. - area lateral: 2πrh. area total: 2πr2 + 2πrh. cone reto (raio r, altura h, geratriz g) - volume: v = (1/3)·πr2h. - geratriz: g2 = r2 + h2. area lateral: πrg. esfera (raio r) - volume: v = (4/3)·πr3. area da superficie: a = 4πr2. unidades de capacidade - 1 cm3 = 1 ml; 1 dm3 = 1 l; 1 m3 = 1000 l. exemplo 1 — caixa-d’agua cilindrica uma caixa-d’agua cilindrica tem raio de 1 m e altura de 2 m. quantos litros ela comporta? use π ≈ 3,14. 1. v = πr2h = π·12·2 = 2π m3. 2. com π ≈ 3,14: v ≈ 6,28 m3. 3. como 1 m3 = 1000 l, a caixa comporta cerca de 6.280 litros. exemplo 2 — cone: geratriz, area lateral e volume um cone reto tem raio da base 3 cm e altura 4 cm. 1. geratriz: g2 = 32 + 42 = 9 + 16 = 25, entao g = 5 cm. 2. area lateral: πrg = π·3·5 = 15π cm2. 3. volume: v = (1/3)·π·32·4 = (1/3)·36π = 12π cm3. exemplo 3 — esfera uma bola tem raio de 6 cm. qual e o seu volume e a area da sua superficie? 1. volume: v = (4/3)·π·63 = (4/3)·216π = 288π cm3. 2. area: a = 4π·62 = 4·36π = 144π cm2. resumo - area em unidades quadradas; volume em unidades cubicas. - prisma e cilindro: v = (area da base)·(altura). - cone: um terco do cilindro de mesma base e altura. - esfera: v = (4/3)πr3 e a = 4πr2. - para capacidade: 1 dm3 = 1 l e 1 cm3 = 1 ml.');
INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (5, 1, 'trigonometria', 2, 'Trigonometria', 'Estudo de seno, cosseno, tangente e do ciclo trigonométrico.', 'Usar seno, cosseno e tangente no triângulo retângulo, converter graus em radianos e localizar ângulos e sinais no ciclo trigonométrico.', 2, 'trigonometria estudo de seno, cosseno, tangente e do ciclo trigonometrico. usar seno, cosseno e tangente no triangulo retangulo, converter graus em radianos e localizar angulos e sinais no ciclo trigonometrico. angulos e medidas a trigonometria relaciona os angulos de um triangulo com as medidas dos seus lados. com ela e possivel calcular alturas e distancias dificeis de medir diretamente, como a altura de um predio a partir da sua sombra. no triangulo retangulo, para um angulo agudo θ, chamamos de hipotenusa o maior lado (oposto ao angulo reto), de cateto oposto o lado em frente a θ e de cateto adjacente o lado que forma θ junto com a hipotenusa. o ciclo trigonometrico e uma circunferencia de raio 1 centrada na origem. cada angulo corresponde a um ponto (cos θ, sen θ), o que permite falar de seno e cosseno de angulos maiores que 90° e de seus sinais. conceitos e formulas no triangulo retangulo (θ agudo) - sen θ = cateto oposto / hipotenusa - cos θ = cateto adjacente / hipotenusa - tg θ = cateto oposto / cateto adjacente - teorema de pitagoras: hipotenusa2 = cateto2 + cateto2. valores notaveis - 30°: sen = 1/2; cos = √3/2; tg = √3/3. - 45°: sen = √2/2; cos = √2/2; tg = 1. - 60°: sen = √3/2; cos = 1/2; tg = √3. relacoes (valem para qualquer angulo) - sen2θ + cos2θ = 1. - tg θ = sen θ / cos θ, desde que cos θ = 0. radianos e ciclo - π rad = 180°. para converter graus em radianos, multiplique por π/180. - sinais: 1º quadrante (0° a 90°) seno e cosseno positivos; 2º (90° a 180°) seno positivo e cosseno negativo; 3º (180° a 270°) ambos negativos; 4º (270° a 360°) seno negativo e cosseno positivo. exemplo 1 — altura de uma rampa uma rampa reta de 8 m de comprimento forma um angulo de 30° com o chao. a que altura ela chega? 1. a rampa e a hipotenusa (8 m) e a altura e o cateto oposto ao angulo de 30°. 2. sen 30° = altura / 8 → altura = 8·(1/2) = 4 m. 3. a distancia horizontal e o cateto adjacente: 8·cos 30° = 8·√3/2 = 4√3 ≈ 6,93 m. exemplo 2 — usando a relacao fundamental sabendo que θ e agudo e sen θ = 3/5, calcule cos θ e tg θ. 1. sen2θ + cos2θ = 1 → 9/25 + cos2θ = 1 → cos2θ = 16/25. 2. como θ e agudo, o cosseno e positivo: cos θ = 4/5. 3. tg θ = sen θ / cos θ = (3/5) / (4/5) = 3/4. exemplo 3 — radianos e ciclo trigonometrico converta 150° para radianos e calcule sen 150°. 1. 150·π/180 = 5π/6 rad. 2. 150° esta no 2º quadrante, onde o seno e positivo. 3. o angulo que falta para 180° e 30°, entao sen 150° = sen 30° = 1/2. resumo - sen = oposto/hipotenusa; cos = adjacente/hipotenusa; tg = oposto/adjacente. - decore os valores de 30°, 45° e 60°. - sen2θ + cos2θ = 1 e tg θ = sen θ / cos θ. - 180° = π rad; o quadrante define os sinais de seno e cosseno.');
INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (6, 1, 'analise-combinatoria-e-probabilidade', 2, 'Análise Combinatória e Probabilidade', 'Técnicas de contagem e cálculo de chances de um evento acontecer.', 'Contar possibilidades com o princípio multiplicativo, permutações, arranjos e combinações, e calcular probabilidades simples, complementares e de eventos independentes.', 3, 'analise combinatoria e probabilidade tecnicas de contagem e calculo de chances de um evento acontecer. contar possibilidades com o principio multiplicativo, permutacoes, arranjos e combinacoes, e calcular probabilidades simples, complementares e de eventos independentes. contar sem listar tudo a analise combinatoria ensina a contar possibilidades sem precisar escrever todas elas. a pergunta central e: a ordem dos elementos escolhidos importa? - se a ordem importa (senhas, podios, presidente e vice), usamos o principio multiplicativo, permutacoes ou arranjos. - se a ordem nao importa (comissoes, duplas, grupos), usamos combinacoes. a probabilidade mede a chance de algo acontecer, comparando os casos que nos interessam (favoraveis) com todos os casos possiveis. ela usa a contagem para encontrar esses numeros. conceitos e formulas contagem - principio multiplicativo: se uma etapa tem m opcoes e outra, independente, tem n opcoes, as duas juntas tem m·n possibilidades. - fatorial (n natural): n! = n·(n − 1)·...·2·1, com 0! = 1. - permutacao de n elementos distintos: pn = n!. - permutacao com repeticao (elementos repetidos k1, k2, ... vezes): n! / (k1!·k2!·...). - arranjo (ordem importa, p ≤ n): an,p = n! / (n − p)!. - combinacao (ordem nao importa, p ≤ n): cn,p = n! / (p!·(n − p)!). probabilidade (todos os resultados igualmente provaveis) - p(a) = numero de casos favoraveis / numero de casos possiveis, com 0 ≤ p(a) ≤ 1. - evento complementar: p(nao a) = 1 − p(a). - eventos independentes: p(a e b) = p(a)·p(b). exemplo 1 — senhas (ordem importa) quantas senhas de 3 digitos podem ser formadas com os algarismos de 0 a 9? 1. com repeticao permitida: cada posicao tem 10 opcoes → 10·10·10 = 1000 senhas. 2. sem repetir algarismos: 10 opcoes, depois 9, depois 8 → 10·9·8 = 720 senhas. 3. o segundo caso e o arranjo a10,3 = 10!/7! = 720. exemplo 2 — comissao (ordem nao importa) de 6 alunos, quantas comissoes de 3 pessoas podem ser formadas? 1. trocar a ordem das pessoas nao muda a comissao, entao e combinacao. 2. c6,3 = 6! / (3!·3!) = 720 / (6·6) = 20 comissoes. exemplo 3 — probabilidade com dois dados dois dados comuns sao lancados. qual e a probabilidade de a soma ser 7? 1. casos possiveis: 6·6 = 36 pares de resultados. 2. casos favoraveis: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) → 6 pares. 3. p = 6/36 = 1/6. resumo - pergunte sempre se a ordem importa: sim → arranjo/permutacao; nao → combinacao. - principio multiplicativo: multiplique as opcoes de cada etapa. - p(a) = favoraveis / possiveis; \"pelo menos um\" costuma ser mais facil pelo complementar: 1 − p(nenhum).');
INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (7, 1, 'geometria-analitica', 3, 'Geometria Analítica', 'Estudo de pontos, retas e circunferências usando coordenadas no plano.', 'Calcular distância e ponto médio entre pontos, determinar a equação de uma reta e identificar centro e raio de uma circunferência no plano cartesiano.', 1, 'geometria analitica estudo de pontos, retas e circunferencias usando coordenadas no plano. calcular distancia e ponto medio entre pontos, determinar a equacao de uma reta e identificar centro e raio de uma circunferencia no plano cartesiano. geometria com coordenadas na geometria analitica, cada ponto do plano e descrito por um par ordenado (x, y). assim, problemas de geometria viram contas: a distancia entre duas cidades em um mapa, a inclinacao de uma rua ou o alcance de uma antena podem ser calculados com formulas. - uma reta e descrita por uma equacao como y = 2x + 1: todos os pontos que satisfazem a equacao estao na reta. - o coeficiente angular mede a inclinacao da reta: quanto y varia quando x aumenta 1 unidade. - uma circunferencia e o conjunto de pontos que estao a mesma distancia (o raio) de um ponto fixo (o centro). conceitos e formulas considere a(xa, ya) e b(xb, yb). pontos - distancia: dab = √((xb − xa)2 + (yb − ya)2). - ponto medio: m = ((xa + xb)/2, (ya + yb)/2). retas - coeficiente angular: m = (yb − ya) / (xb − xa), valido se xa = xb. retas verticais (x constante) nao tem coeficiente angular. - reta que passa por (x0, y0) com coeficiente m: y − y0 = m(x − x0). - equacao reduzida: y = mx + n, em que n e onde a reta corta o eixo y. - retas paralelas (nao verticais) tem o mesmo m. retas perpendiculares (nenhuma vertical) tem m1·m2 = −1. circunferencia - centro c(a, b) e raio r > 0: (x − a)2 + (y − b)2 = r2. - atencao aos sinais: (x + 1)2 = (x − (−1))2, entao a = −1. exemplo 1 — distancia, ponto medio e inclinacao considere a(1, 2) e b(4, 6). 1. distancia: d = √((4 − 1)2 + (6 − 2)2) = √(9 + 16) = √25 = 5. 2. ponto medio: m = ((1 + 4)/2, (2 + 6)/2) = (2,5; 4). 3. coeficiente angular: m = (6 − 2)/(4 − 1) = 4/3. exemplo 2 — equacao de uma reta encontre a equacao da reta que passa por a(1, 3) e tem coeficiente angular 2. o ponto p(2, 5) pertence a ela? 1. y − 3 = 2(x − 1) → y − 3 = 2x − 2 → y = 2x + 1. 2. testando p: para x = 2, y = 2·2 + 1 = 5. como deu 5, p pertence a reta. exemplo 3 — circunferencia escreva a equacao da circunferencia de centro (2, −1) e raio 3. o ponto (5, −1) esta nela? 1. (x − 2)2 + (y − (−1))2 = 32 → (x − 2)2 + (y + 1)2 = 9. 2. para (5, −1): (5 − 2)2 + (−1 + 1)2 = 9 + 0 = 9. o ponto pertence a circunferencia. resumo - distancia vem de pitagoras; ponto medio e a media das coordenadas. - m = δy/δx mede a inclinacao; y = mx + n e a forma reduzida. - paralelas: mesmo m. perpendiculares: m1·m2 = −1. - circunferencia: (x − a)2 + (y − b)2 = r2; o centro aparece com os sinais trocados.');
INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (8, 1, 'estatistica', 3, 'Estatística', 'Leitura de tabelas, gráficos, média, mediana e moda.', 'Calcular e interpretar média (simples e ponderada), mediana e moda, e ler informações em tabelas de frequência e gráficos.', 2, 'estatistica leitura de tabelas, graficos, media, mediana e moda. calcular e interpretar media (simples e ponderada), mediana e moda, e ler informacoes em tabelas de frequencia e graficos. resumindo dados com poucos numeros a estatistica organiza e interpreta dados, como notas de uma turma, precos ou resultados de pesquisas. as medidas de tendencia central resumem um conjunto de dados em um unico valor \"tipico\": - a media distribui o total igualmente entre os valores; - a mediana e o valor do meio, depois de colocar os dados em ordem; - a moda e o valor que aparece mais vezes. a media e sensivel a valores muito altos ou muito baixos; a mediana, nao. por isso, em salarios ou precos de imoveis, a mediana muitas vezes representa melhor a situacao tipica. tabelas de frequencia mostram quantas vezes cada valor aparece, e graficos (barras, linhas e setores) ajudam a comparar e a ver tendencias. conceitos e formulas - media aritmetica: soma de todos os valores ÷ quantidade de valores. - media ponderada: (x1·p1 + x2·p2 + ... + xn·pn) ÷ (p1 + p2 + ... + pn), em que p sao os pesos. - mediana: coloque os dados em ordem. se a quantidade n for impar, e o valor na posicao (n + 1)/2. se n for par, e a media dos dois valores centrais. - moda: valor de maior frequencia. um conjunto pode ter uma moda, mais de uma (bimodal) ou nenhuma (amodal). - frequencia relativa: frequencia do valor ÷ total de dados (multiplique por 100 para obter a porcentagem). - grafico de setores: o angulo de cada fatia e a sua porcentagem de 360°. exemplo 1 — media, mediana e moda notas de um aluno: 5, 7, 7, 8, 9 e 6. 1. media: (5 + 7 + 7 + 8 + 9 + 6)/6 = 42/6 = 7. 2. mediana: em ordem, 5, 6, 7, 7, 8, 9. como n = 6 e par, a mediana e (7 + 7)/2 = 7. 3. moda: 7, que aparece duas vezes. exemplo 2 — media ponderada a nota final de uma disciplina tem prova com peso 2 e trabalho com peso 1. um aluno tirou 6 na prova e 9 no trabalho. 1. multiplique cada nota pelo seu peso: 6·2 = 12 e 9·1 = 9. 2. some e divida pela soma dos pesos: (12 + 9)/(2 + 1) = 21/3 = 7. 3. a nota final e 7. a media simples seria 7,5: a prova, com peso maior, \"puxou\" a nota para baixo. exemplo 3 — frequencia e grafico de setores em uma pesquisa com 40 alunos sobre o esporte preferido, 10 escolheram futebol. 1. frequencia relativa: 10/40 = 0,25 = 25%. 2. no grafico de setores, a fatia de futebol tem 25% de 360° = 0,25·360° = 90°. resumo - media = soma ÷ quantidade; na ponderada, cada valor conta conforme seu peso. - mediana: sempre ordene os dados antes; com quantidade par, faca a media dos dois centrais. - moda: o valor mais frequente. - porcentagem de um setor × 360° = angulo da fatia.');
INSERT INTO `topics` (`id`, `subject_id`, `slug`, `school_year`, `title`, `summary`, `objective`, `position`, `search_text`) VALUES (9, 1, 'matematica-financeira', 3, 'Matemática Financeira', 'Porcentagem, juros simples e juros compostos para o dia a dia.', 'Calcular porcentagens, aumentos e descontos e comparar juros simples e compostos, usando taxa e período na mesma unidade de tempo.', 3, 'matematica financeira porcentagem, juros simples e juros compostos para o dia a dia. calcular porcentagens, aumentos e descontos e comparar juros simples e compostos, usando taxa e periodo na mesma unidade de tempo. dinheiro ao longo do tempo a matematica financeira ajuda a decidir entre pagar a vista ou parcelado, entender descontos e saber quanto uma divida ou investimento cresce. porcentagem e uma fracao com denominador 100: 15% = 15/100 = 0,15. juros sao o valor pago pelo uso de um dinheiro durante um tempo: - nos juros simples, os juros de cada periodo sao sempre calculados sobre o valor inicial (capital); - nos juros compostos, os juros de cada periodo sao somados ao saldo e passam a render juros tambem (\"juros sobre juros\"). por isso, com a mesma taxa, os juros compostos crescem mais rapido com o tempo. a maioria dos financiamentos, cartoes de credito e investimentos usa juros compostos. conceitos e formulas notacao: c = capital (valor inicial), i = taxa de juros na forma decimal, t = numero de periodos, j = juros, m = montante (valor final). condicao essencial: a taxa e o tempo precisam estar na mesma unidade. taxa ao mes → tempo em meses; taxa ao ano → tempo em anos. porcentagem - p% de v = (p/100)·v. - aumento de p%: v·(1 + p/100). desconto de p%: v·(1 − p/100). - aumentos e descontos sucessivos: multiplique os fatores (eles nao se somam). juros simples - j = c·i·t - m = c + j = c·(1 + i·t) juros compostos - m = c·(1 + i)t - j = m − c exemplo 1 — desconto a vista um celular custa r$ 1.200,00 e tem 15% de desconto no pagamento a vista. qual e o preco a vista? 1. fator de desconto: 1 − 0,15 = 0,85. 2. preco: 1200·0,85 = 1020. o preco a vista e r$ 1.020,00 (economia de r$ 180,00). exemplo 2 — juros simples r$ 2.000,00 sao aplicados a juros simples de 1,5% ao mes durante 8 meses. qual e o montante? 1. taxa e tempo estao em meses: i = 0,015 e t = 8. 2. j = 2000·0,015·8 = 240. 3. m = 2000 + 240 = 2240. o montante e r$ 2.240,00. exemplo 3 — juros compostos × juros simples r$ 1.000,00 sao aplicados a 2% ao mes durante 3 meses. compare juros compostos e simples. 1. compostos: m = 1000·(1,02)3 = 1000·1,061208 ≈ 1061,21. montante de r$ 1.061,21. 2. simples: m = 1000·(1 + 0,02·3) = 1000·1,06 = 1060. montante de r$ 1.060,00. 3. nos compostos, o montante e maior porque os juros de cada mes tambem rendem juros. resumo - transforme a porcentagem em decimal antes de calcular. - aumento: multiplique por (1 + taxa); desconto: por (1 − taxa). - simples: m = c·(1 + i·t). compostos: m = c·(1 + i)t. - taxa e tempo sempre na mesma unidade.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (1, 1, 1, 'explicacao', 'O que é uma função', 'Uma função é uma regra que associa cada valor de entrada x a um único valor de saída y = f(x). No dia a dia, o preço de uma corrida que depende da distância ou a altura de uma bola que depende do tempo são exemplos de funções.\n\nNa **função do 1º grau**, a variável x aparece com expoente 1 e o gráfico é uma reta: a saída cresce ou diminui sempre no mesmo ritmo.\n\nNa **função do 2º grau**, aparece o termo x^{2} e o gráfico é uma curva chamada parábola. Ela tem um ponto especial, o vértice, onde a função atinge seu valor mínimo ou máximo.\n\nAs **raízes** (ou zeros) de uma função são os valores de x em que f(x) = 0. No gráfico, são os pontos em que a curva toca o eixo x.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (2, 1, 2, 'formulas', 'Conceitos e fórmulas', '**Função do 1º grau**\n- Forma: f(x) = ax + b, com a ≠ 0.\n- a é a taxa de variação: se a > 0, a função é crescente; se a < 0, é decrescente.\n- b é o valor de f(0): a reta corta o eixo y no ponto (0, b).\n- Raiz: x = −b/a (só existe divisão porque a ≠ 0).\n\n**Função do 2º grau**\n- Forma: f(x) = ax^{2} + bx + c, com a ≠ 0.\n- Se a > 0, a parábola tem concavidade para cima e o vértice é o ponto de mínimo; se a < 0, concavidade para baixo e o vértice é o ponto de máximo.\n- Discriminante: Δ = b^{2} − 4ac. Se Δ > 0, há duas raízes reais diferentes; se Δ = 0, uma raiz real (dupla); se Δ < 0, nenhuma raiz real.\n- Fórmula de Bhaskara: x = (−b ± √Δ) / (2a), usada apenas quando Δ ≥ 0.\n- Vértice: x_{v} = −b/(2a) e y_{v} = −Δ/(4a), ou y_{v} = f(x_{v}).');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (3, 1, 3, 'exemplo', 'Exemplo 1 — Preço de uma corrida (1º grau)', 'Uma corrida de aplicativo custa R$ 5,00 fixos mais R$ 2,00 por quilômetro. Qual é o preço de uma corrida de 8 km? E quantos quilômetros é possível rodar com R$ 29,00?\n\n1. O valor fixo é b = 5 e o valor por quilômetro é a = 2. Então C(x) = 2x + 5.\n2. Para 8 km: C(8) = 2·8 + 5 = 16 + 5 = 21. A corrida custa R$ 21,00.\n3. Para R$ 29,00: 2x + 5 = 29 → 2x = 24 → x = 12. É possível rodar 12 km.\n4. Como a = 2 > 0, a função é crescente: quanto maior a distância, maior o preço.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (4, 1, 4, 'exemplo', 'Exemplo 2 — Raízes e vértice (2º grau)', 'Vamos analisar f(x) = x^{2} − 6x + 8.\n\n1. Coeficientes: a = 1, b = −6 e c = 8.\n2. Discriminante: Δ = (−6)^{2} − 4·1·8 = 36 − 32 = 4. Como Δ > 0, há duas raízes reais.\n3. Raízes: x = (6 ± √4) / 2 = (6 ± 2) / 2, então x = 4 ou x = 2.\n4. Vértice: x_{v} = 6/2 = 3 e y_{v} = f(3) = 9 − 18 + 8 = −1. Logo, V = (3, −1).\n5. Como a = 1 > 0, a concavidade é para cima e o vértice é o ponto de mínimo.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (5, 1, 5, 'exemplo', 'Exemplo 3 — Altura máxima de uma bola (2º grau)', 'A altura de uma bola, em metros, t segundos após o chute é h(t) = −5t^{2} + 20t. Qual é a altura máxima?\n\n1. Como a = −5 < 0, a parábola tem concavidade para baixo e o vértice é o ponto de máximo.\n2. Instante do máximo: t_{v} = −20/(2·(−5)) = 2 segundos.\n3. Altura máxima: h(2) = −5·4 + 20·2 = −20 + 40 = 20 metros.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (6, 1, 6, 'resumo', 'Resumo', '- 1º grau: f(x) = ax + b, gráfico reta; raiz x = −b/a; o sinal de a indica se cresce ou decresce.\n- 2º grau: f(x) = ax^{2} + bx + c, gráfico parábola; o sinal de a indica a concavidade.\n- Δ = b^{2} − 4ac decide quantas raízes reais existem.\n- O vértice (x_{v}, y_{v}) dá o valor mínimo (a > 0) ou máximo (a < 0) da função.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (7, 2, 1, 'explicacao', 'Sequências com padrão', 'Uma progressão é uma sequência de números que segue uma regra fixa.\n\nNa **progressão aritmética (PA)**, cada termo é obtido **somando** sempre o mesmo valor ao anterior. Esse valor é a razão r. Exemplo: (3, 7, 11, 15, ...) tem r = 4. Aparece em situações como economizar um valor que aumenta a mesma quantia todo mês.\n\nNa **progressão geométrica (PG)**, cada termo é obtido **multiplicando** sempre pelo mesmo valor. Esse valor é a razão q. Exemplo: (2, 6, 18, 54, ...) tem q = 3. Aparece em crescimentos que dobram ou triplicam, como a multiplicação de bactérias.\n\nPara descobrir o tipo: se a diferença entre termos vizinhos é constante, é PA; se a divisão entre termos vizinhos é constante, é PG.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (8, 2, 2, 'formulas', 'Conceitos e fórmulas', '**Progressão aritmética** (n é a posição do termo, inteiro e n ≥ 1)\n- Razão: r = a_{2} − a_{1}.\n- Termo geral: a_{n} = a_{1} + (n − 1)·r.\n- Soma dos n primeiros termos: S_{n} = (a_{1} + a_{n})·n / 2.\n\n**Progressão geométrica** (a_{1} ≠ 0)\n- Razão: q = a_{2} / a_{1}.\n- Termo geral: a_{n} = a_{1}·q^{n − 1}.\n- Soma dos n primeiros termos: S_{n} = a_{1}·(q^{n} − 1) / (q − 1), válida para q ≠ 1. Se q = 1, todos os termos são iguais e S_{n} = n·a_{1}.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (9, 2, 3, 'exemplo', 'Exemplo 1 — Economia mensal (PA)', 'Uma pessoa guarda R$ 50,00 no primeiro mês e, a cada mês, guarda R$ 10,00 a mais do que no mês anterior. Quanto ela guarda no 12º mês? E quanto terá guardado ao todo em 12 meses?\n\n1. Os valores formam uma PA com a_{1} = 50 e r = 10.\n2. 12º termo: a_{12} = 50 + (12 − 1)·10 = 50 + 110 = 160. No 12º mês ela guarda R$ 160,00.\n3. Soma: S_{12} = (50 + 160)·12 / 2 = 210·6 = 1260. Ao todo, R$ 1.260,00.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (10, 2, 4, 'exemplo', 'Exemplo 2 — Crescimento de bactérias (PG)', 'Uma cultura começa com 300 bactérias e a quantidade dobra a cada hora. Quantas bactérias haverá ao final de 5 horas?\n\n1. A sequência (300, 600, 1200, ...) é uma PG com a_{1} = 300 (início) e q = 2.\n2. O início é o 1º termo; ao final de 5 horas estamos no 6º termo.\n3. a_{6} = 300·2^{5} = 300·32 = 9600. Haverá 9.600 bactérias.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (11, 2, 5, 'exemplo', 'Exemplo 3 — Soma de uma PG', 'Qual é a soma dos 5 primeiros termos da PG (2, 6, 18, ...)?\n\n1. a_{1} = 2 e q = 6/2 = 3 (q ≠ 1, então a fórmula da soma pode ser usada).\n2. S_{5} = 2·(3^{5} − 1) / (3 − 1) = 2·(243 − 1) / 2 = 242.\n3. Conferindo: 2 + 6 + 18 + 54 + 162 = 242.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (12, 2, 6, 'resumo', 'Resumo', '- PA: soma-se a razão r; a_{n} = a_{1} + (n − 1)·r; S_{n} = (a_{1} + a_{n})·n / 2.\n- PG: multiplica-se pela razão q; a_{n} = a_{1}·q^{n − 1}; S_{n} = a_{1}·(q^{n} − 1)/(q − 1), com q ≠ 1.\n- Atenção à posição do termo: o primeiro termo é a_{1}, não a_{0}.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (13, 3, 1, 'explicacao', 'Crescimento rápido e operação inversa', 'Na **função exponencial**, a variável está no expoente: f(x) = 2^{x}. A cada passo, o valor é multiplicado pela mesma base, por isso o crescimento (ou a queda) é muito rápido. Ela descreve juros compostos, crescimento de populações e decaimento de substâncias.\n\nO **logaritmo** responde à pergunta inversa: \"a que expoente devo elevar a base para obter este número?\". Como 2^{3} = 8, dizemos que log_{2} 8 = 3.\n\nLogaritmos são úteis quando a incógnita está no expoente e não é possível escrever os dois lados da equação na mesma base.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (14, 3, 2, 'formulas', 'Conceitos e fórmulas', '**Função exponencial**\n- f(x) = a^{x}, com a > 0 e a ≠ 1.\n- Se a > 1, a função é crescente; se 0 < a < 1, é decrescente.\n- O gráfico passa por (0, 1) e f(x) > 0 para todo x real.\n- Propriedades das potências: a^{m}·a^{n} = a^{m + n}; a^{m} / a^{n} = a^{m − n}; (a^{m})^{n} = a^{m·n}; a^{0} = 1.\n- Equação exponencial: se a > 0 e a ≠ 1, então a^{x} = a^{y} quando, e somente quando, x = y.\n\n**Logaritmos**\n- Definição: log_{a} b = x significa a^{x} = b, com a > 0, a ≠ 1 e b > 0.\n- Quando a base não aparece, ela é 10: log 1000 = 3.\n- Para m > 0 e n > 0: log_{a}(m·n) = log_{a} m + log_{a} n; log_{a}(m/n) = log_{a} m − log_{a} n; log_{a}(m^{k}) = k·log_{a} m.\n- Mudança de base: log_{a} b = log b / log a.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (15, 3, 3, 'exemplo', 'Exemplo 1 — Equação exponencial', 'Resolva 3^{x + 1} = 81.\n\n1. Escreva 81 como potência de 3: 81 = 3^{4}.\n2. A equação fica 3^{x + 1} = 3^{4}. Como as bases são iguais (e válidas), os expoentes são iguais.\n3. x + 1 = 4 → x = 3.\n4. Conferindo: 3^{3 + 1} = 3^{4} = 81.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (16, 3, 4, 'exemplo', 'Exemplo 2 — Calculando logaritmos', 'a) Quanto vale log_{2} 32?\n1. Procuramos x tal que 2^{x} = 32. Como 2^{5} = 32, log_{2} 32 = 5.\n\nb) Sabendo que log 2 ≈ 0,301, quanto vale log 8?\n1. 8 = 2^{3}, então log 8 = log 2^{3} = 3·log 2.\n2. log 8 ≈ 3·0,301 = 0,903.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (17, 3, 5, 'exemplo', 'Exemplo 3 — Quando a população dobra', 'Uma cidade tem 10.000 habitantes e cresce 10% ao ano, ou seja, P(t) = 10000·1,1^{t}, com t em anos. Em quanto tempo a população dobra? Use log 2 ≈ 0,301 e log 1,1 ≈ 0,0414.\n\n1. Dobrar significa P(t) = 20000: 10000·1,1^{t} = 20000 → 1,1^{t} = 2.\n2. Não dá para escrever 2 como potência de 1,1, então aplicamos log nos dois lados: t·log 1,1 = log 2.\n3. t = 0,301 / 0,0414 ≈ 7,3. A população dobra em pouco mais de 7 anos.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (18, 3, 6, 'resumo', 'Resumo', '- Exponencial: f(x) = a^{x}, a > 0 e a ≠ 1; cresce se a > 1 e decresce se 0 < a < 1.\n- Mesma base dos dois lados → iguale os expoentes.\n- log_{a} b = x ⇔ a^{x} = b (a > 0, a ≠ 1, b > 0).\n- Produto vira soma, divisão vira subtração e expoente \"desce\" multiplicando.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (19, 4, 1, 'explicacao', 'Medindo objetos em três dimensões', 'A geometria espacial estuda sólidos, como caixas, latas, casquinhas de sorvete e bolas.\n\n- A **área** mede a superfície que cobre o sólido (quanto papel seria preciso para embrulhá-lo). É dada em unidades quadradas, como cm^{2} e m^{2}.\n- O **volume** mede o espaço ocupado (quanto cabe dentro). É dado em unidades cúbicas, como cm^{3} e m^{3}.\n\nPrismas e cilindros têm duas bases iguais e paralelas: o volume é a área da base vezes a altura. O cone é como um cilindro que \"afina\" até um ponto, e seu volume é um terço do cilindro de mesma base e altura. A esfera tem fórmulas próprias, que dependem só do raio.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (20, 4, 2, 'formulas', 'Conceitos e fórmulas', 'Todas as medidas devem estar na mesma unidade antes de calcular. Respostas podem deixar π indicado (ex.: 12π cm^{3}) ou usar uma aproximação, como π ≈ 3,14, quando o enunciado pedir.\n\n**Prismas** (A_{b} = área da base, h = altura)\n- Volume: V = A_{b}·h.\n- Cubo de aresta a: V = a^{3}; área total A = 6a^{2}.\n- Paralelepípedo de dimensões a, b e c: V = a·b·c; área total A = 2(ab + ac + bc).\n\n**Cilindro** (raio r, altura h)\n- Área da base: A_{b} = πr^{2}. Volume: V = πr^{2}h.\n- Área lateral: 2πrh. Área total: 2πr^{2} + 2πrh.\n\n**Cone reto** (raio r, altura h, geratriz g)\n- Volume: V = (1/3)·πr^{2}h.\n- Geratriz: g^{2} = r^{2} + h^{2}. Área lateral: πrg.\n\n**Esfera** (raio r)\n- Volume: V = (4/3)·πr^{3}. Área da superfície: A = 4πr^{2}.\n\n**Unidades de capacidade**\n- 1 cm^{3} = 1 mL; 1 dm^{3} = 1 L; 1 m^{3} = 1000 L.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (21, 4, 3, 'exemplo', 'Exemplo 1 — Caixa-d’água cilíndrica', 'Uma caixa-d’água cilíndrica tem raio de 1 m e altura de 2 m. Quantos litros ela comporta? Use π ≈ 3,14.\n\n1. V = πr^{2}h = π·1^{2}·2 = 2π m^{3}.\n2. Com π ≈ 3,14: V ≈ 6,28 m^{3}.\n3. Como 1 m^{3} = 1000 L, a caixa comporta cerca de 6.280 litros.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (22, 4, 4, 'exemplo', 'Exemplo 2 — Cone: geratriz, área lateral e volume', 'Um cone reto tem raio da base 3 cm e altura 4 cm.\n\n1. Geratriz: g^{2} = 3^{2} + 4^{2} = 9 + 16 = 25, então g = 5 cm.\n2. Área lateral: πrg = π·3·5 = 15π cm^{2}.\n3. Volume: V = (1/3)·π·3^{2}·4 = (1/3)·36π = 12π cm^{3}.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (23, 4, 5, 'exemplo', 'Exemplo 3 — Esfera', 'Uma bola tem raio de 6 cm. Qual é o seu volume e a área da sua superfície?\n\n1. Volume: V = (4/3)·π·6^{3} = (4/3)·216π = 288π cm^{3}.\n2. Área: A = 4π·6^{2} = 4·36π = 144π cm^{2}.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (24, 4, 6, 'resumo', 'Resumo', '- Área em unidades quadradas; volume em unidades cúbicas.\n- Prisma e cilindro: V = (área da base)·(altura).\n- Cone: um terço do cilindro de mesma base e altura.\n- Esfera: V = (4/3)πr^{3} e A = 4πr^{2}.\n- Para capacidade: 1 dm^{3} = 1 L e 1 cm^{3} = 1 mL.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (25, 5, 1, 'explicacao', 'Ângulos e medidas', 'A trigonometria relaciona os **ângulos** de um triângulo com as **medidas** dos seus lados. Com ela é possível calcular alturas e distâncias difíceis de medir diretamente, como a altura de um prédio a partir da sua sombra.\n\nNo triângulo retângulo, para um ângulo agudo θ, chamamos de **hipotenusa** o maior lado (oposto ao ângulo reto), de **cateto oposto** o lado em frente a θ e de **cateto adjacente** o lado que forma θ junto com a hipotenusa.\n\nO **ciclo trigonométrico** é uma circunferência de raio 1 centrada na origem. Cada ângulo corresponde a um ponto (cos θ, sen θ), o que permite falar de seno e cosseno de ângulos maiores que 90° e de seus sinais.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (26, 5, 2, 'formulas', 'Conceitos e fórmulas', '**No triângulo retângulo** (θ agudo)\n- sen θ = cateto oposto / hipotenusa\n- cos θ = cateto adjacente / hipotenusa\n- tg θ = cateto oposto / cateto adjacente\n- Teorema de Pitágoras: hipotenusa^{2} = cateto^{2} + cateto^{2}.\n\n**Valores notáveis**\n- 30°: sen = 1/2; cos = √3/2; tg = √3/3.\n- 45°: sen = √2/2; cos = √2/2; tg = 1.\n- 60°: sen = √3/2; cos = 1/2; tg = √3.\n\n**Relações** (valem para qualquer ângulo)\n- sen^{2}θ + cos^{2}θ = 1.\n- tg θ = sen θ / cos θ, desde que cos θ ≠ 0.\n\n**Radianos e ciclo**\n- π rad = 180°. Para converter graus em radianos, multiplique por π/180.\n- Sinais: 1º quadrante (0° a 90°) seno e cosseno positivos; 2º (90° a 180°) seno positivo e cosseno negativo; 3º (180° a 270°) ambos negativos; 4º (270° a 360°) seno negativo e cosseno positivo.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (27, 5, 3, 'exemplo', 'Exemplo 1 — Altura de uma rampa', 'Uma rampa reta de 8 m de comprimento forma um ângulo de 30° com o chão. A que altura ela chega?\n\n1. A rampa é a hipotenusa (8 m) e a altura é o cateto oposto ao ângulo de 30°.\n2. sen 30° = altura / 8 → altura = 8·(1/2) = 4 m.\n3. A distância horizontal é o cateto adjacente: 8·cos 30° = 8·√3/2 = 4√3 ≈ 6,93 m.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (28, 5, 4, 'exemplo', 'Exemplo 2 — Usando a relação fundamental', 'Sabendo que θ é agudo e sen θ = 3/5, calcule cos θ e tg θ.\n\n1. sen^{2}θ + cos^{2}θ = 1 → 9/25 + cos^{2}θ = 1 → cos^{2}θ = 16/25.\n2. Como θ é agudo, o cosseno é positivo: cos θ = 4/5.\n3. tg θ = sen θ / cos θ = (3/5) / (4/5) = 3/4.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (29, 5, 5, 'exemplo', 'Exemplo 3 — Radianos e ciclo trigonométrico', 'Converta 150° para radianos e calcule sen 150°.\n\n1. 150·π/180 = 5π/6 rad.\n2. 150° está no 2º quadrante, onde o seno é positivo.\n3. O ângulo que falta para 180° é 30°, então sen 150° = sen 30° = 1/2.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (30, 5, 6, 'resumo', 'Resumo', '- sen = oposto/hipotenusa; cos = adjacente/hipotenusa; tg = oposto/adjacente.\n- Decore os valores de 30°, 45° e 60°.\n- sen^{2}θ + cos^{2}θ = 1 e tg θ = sen θ / cos θ.\n- 180° = π rad; o quadrante define os sinais de seno e cosseno.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (31, 6, 1, 'explicacao', 'Contar sem listar tudo', 'A análise combinatória ensina a contar possibilidades sem precisar escrever todas elas. A pergunta central é: **a ordem dos elementos escolhidos importa?**\n\n- Se a ordem importa (senhas, pódios, presidente e vice), usamos o princípio multiplicativo, permutações ou arranjos.\n- Se a ordem não importa (comissões, duplas, grupos), usamos combinações.\n\nA **probabilidade** mede a chance de algo acontecer, comparando os casos que nos interessam (favoráveis) com todos os casos possíveis. Ela usa a contagem para encontrar esses números.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (32, 6, 2, 'formulas', 'Conceitos e fórmulas', '**Contagem**\n- Princípio multiplicativo: se uma etapa tem m opções e outra, independente, tem n opções, as duas juntas têm m·n possibilidades.\n- Fatorial (n natural): n! = n·(n − 1)·...·2·1, com 0! = 1.\n- Permutação de n elementos distintos: P_{n} = n!.\n- Permutação com repetição (elementos repetidos k_{1}, k_{2}, ... vezes): n! / (k_{1}!·k_{2}!·...).\n- Arranjo (ordem importa, p ≤ n): A_{n,p} = n! / (n − p)!.\n- Combinação (ordem não importa, p ≤ n): C_{n,p} = n! / (p!·(n − p)!).\n\n**Probabilidade** (todos os resultados igualmente prováveis)\n- P(A) = número de casos favoráveis / número de casos possíveis, com 0 ≤ P(A) ≤ 1.\n- Evento complementar: P(não A) = 1 − P(A).\n- Eventos independentes: P(A e B) = P(A)·P(B).');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (33, 6, 3, 'exemplo', 'Exemplo 1 — Senhas (ordem importa)', 'Quantas senhas de 3 dígitos podem ser formadas com os algarismos de 0 a 9?\n\n1. Com repetição permitida: cada posição tem 10 opções → 10·10·10 = 1000 senhas.\n2. Sem repetir algarismos: 10 opções, depois 9, depois 8 → 10·9·8 = 720 senhas.\n3. O segundo caso é o arranjo A_{10,3} = 10!/7! = 720.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (34, 6, 4, 'exemplo', 'Exemplo 2 — Comissão (ordem não importa)', 'De 6 alunos, quantas comissões de 3 pessoas podem ser formadas?\n\n1. Trocar a ordem das pessoas não muda a comissão, então é combinação.\n2. C_{6,3} = 6! / (3!·3!) = 720 / (6·6) = 20 comissões.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (35, 6, 5, 'exemplo', 'Exemplo 3 — Probabilidade com dois dados', 'Dois dados comuns são lançados. Qual é a probabilidade de a soma ser 7?\n\n1. Casos possíveis: 6·6 = 36 pares de resultados.\n2. Casos favoráveis: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) → 6 pares.\n3. P = 6/36 = 1/6.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (36, 6, 6, 'resumo', 'Resumo', '- Pergunte sempre se a ordem importa: sim → arranjo/permutação; não → combinação.\n- Princípio multiplicativo: multiplique as opções de cada etapa.\n- P(A) = favoráveis / possíveis; \"pelo menos um\" costuma ser mais fácil pelo complementar: 1 − P(nenhum).');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (37, 7, 1, 'explicacao', 'Geometria com coordenadas', 'Na geometria analítica, cada ponto do plano é descrito por um par ordenado (x, y). Assim, problemas de geometria viram contas: a distância entre duas cidades em um mapa, a inclinação de uma rua ou o alcance de uma antena podem ser calculados com fórmulas.\n\n- Uma **reta** é descrita por uma equação como y = 2x + 1: todos os pontos que satisfazem a equação estão na reta.\n- O **coeficiente angular** mede a inclinação da reta: quanto y varia quando x aumenta 1 unidade.\n- Uma **circunferência** é o conjunto de pontos que estão à mesma distância (o raio) de um ponto fixo (o centro).');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (38, 7, 2, 'formulas', 'Conceitos e fórmulas', 'Considere A(x_{A}, y_{A}) e B(x_{B}, y_{B}).\n\n**Pontos**\n- Distância: d_{AB} = √((x_{B} − x_{A})^{2} + (y_{B} − y_{A})^{2}).\n- Ponto médio: M = ((x_{A} + x_{B})/2, (y_{A} + y_{B})/2).\n\n**Retas**\n- Coeficiente angular: m = (y_{B} − y_{A}) / (x_{B} − x_{A}), válido se x_{A} ≠ x_{B}. Retas verticais (x constante) não têm coeficiente angular.\n- Reta que passa por (x_{0}, y_{0}) com coeficiente m: y − y_{0} = m(x − x_{0}).\n- Equação reduzida: y = mx + n, em que n é onde a reta corta o eixo y.\n- Retas paralelas (não verticais) têm o mesmo m. Retas perpendiculares (nenhuma vertical) têm m_{1}·m_{2} = −1.\n\n**Circunferência**\n- Centro C(a, b) e raio r > 0: (x − a)^{2} + (y − b)^{2} = r^{2}.\n- Atenção aos sinais: (x + 1)^{2} = (x − (−1))^{2}, então a = −1.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (39, 7, 3, 'exemplo', 'Exemplo 1 — Distância, ponto médio e inclinação', 'Considere A(1, 2) e B(4, 6).\n\n1. Distância: d = √((4 − 1)^{2} + (6 − 2)^{2}) = √(9 + 16) = √25 = 5.\n2. Ponto médio: M = ((1 + 4)/2, (2 + 6)/2) = (2,5; 4).\n3. Coeficiente angular: m = (6 − 2)/(4 − 1) = 4/3.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (40, 7, 4, 'exemplo', 'Exemplo 2 — Equação de uma reta', 'Encontre a equação da reta que passa por A(1, 3) e tem coeficiente angular 2. O ponto P(2, 5) pertence a ela?\n\n1. y − 3 = 2(x − 1) → y − 3 = 2x − 2 → y = 2x + 1.\n2. Testando P: para x = 2, y = 2·2 + 1 = 5. Como deu 5, P pertence à reta.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (41, 7, 5, 'exemplo', 'Exemplo 3 — Circunferência', 'Escreva a equação da circunferência de centro (2, −1) e raio 3. O ponto (5, −1) está nela?\n\n1. (x − 2)^{2} + (y − (−1))^{2} = 3^{2} → (x − 2)^{2} + (y + 1)^{2} = 9.\n2. Para (5, −1): (5 − 2)^{2} + (−1 + 1)^{2} = 9 + 0 = 9. O ponto pertence à circunferência.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (42, 7, 6, 'resumo', 'Resumo', '- Distância vem de Pitágoras; ponto médio é a média das coordenadas.\n- m = Δy/Δx mede a inclinação; y = mx + n é a forma reduzida.\n- Paralelas: mesmo m. Perpendiculares: m_{1}·m_{2} = −1.\n- Circunferência: (x − a)^{2} + (y − b)^{2} = r^{2}; o centro aparece com os sinais trocados.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (43, 8, 1, 'explicacao', 'Resumindo dados com poucos números', 'A estatística organiza e interpreta dados, como notas de uma turma, preços ou resultados de pesquisas.\n\nAs **medidas de tendência central** resumem um conjunto de dados em um único valor \"típico\":\n- a **média** distribui o total igualmente entre os valores;\n- a **mediana** é o valor do meio, depois de colocar os dados em ordem;\n- a **moda** é o valor que aparece mais vezes.\n\nA média é sensível a valores muito altos ou muito baixos; a mediana, não. Por isso, em salários ou preços de imóveis, a mediana muitas vezes representa melhor a situação típica.\n\n**Tabelas de frequência** mostram quantas vezes cada valor aparece, e **gráficos** (barras, linhas e setores) ajudam a comparar e a ver tendências.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (44, 8, 2, 'formulas', 'Conceitos e fórmulas', '- **Média aritmética**: soma de todos os valores ÷ quantidade de valores.\n- **Média ponderada**: (x_{1}·p_{1} + x_{2}·p_{2} + ... + x_{n}·p_{n}) ÷ (p_{1} + p_{2} + ... + p_{n}), em que p são os pesos.\n- **Mediana**: coloque os dados em ordem. Se a quantidade n for ímpar, é o valor na posição (n + 1)/2. Se n for par, é a média dos dois valores centrais.\n- **Moda**: valor de maior frequência. Um conjunto pode ter uma moda, mais de uma (bimodal) ou nenhuma (amodal).\n- **Frequência relativa**: frequência do valor ÷ total de dados (multiplique por 100 para obter a porcentagem).\n- **Gráfico de setores**: o ângulo de cada fatia é a sua porcentagem de 360°.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (45, 8, 3, 'exemplo', 'Exemplo 1 — Média, mediana e moda', 'Notas de um aluno: 5, 7, 7, 8, 9 e 6.\n\n1. Média: (5 + 7 + 7 + 8 + 9 + 6)/6 = 42/6 = 7.\n2. Mediana: em ordem, 5, 6, 7, 7, 8, 9. Como n = 6 é par, a mediana é (7 + 7)/2 = 7.\n3. Moda: 7, que aparece duas vezes.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (46, 8, 4, 'exemplo', 'Exemplo 2 — Média ponderada', 'A nota final de uma disciplina tem prova com peso 2 e trabalho com peso 1. Um aluno tirou 6 na prova e 9 no trabalho.\n\n1. Multiplique cada nota pelo seu peso: 6·2 = 12 e 9·1 = 9.\n2. Some e divida pela soma dos pesos: (12 + 9)/(2 + 1) = 21/3 = 7.\n3. A nota final é 7. A média simples seria 7,5: a prova, com peso maior, \"puxou\" a nota para baixo.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (47, 8, 5, 'exemplo', 'Exemplo 3 — Frequência e gráfico de setores', 'Em uma pesquisa com 40 alunos sobre o esporte preferido, 10 escolheram futebol.\n\n1. Frequência relativa: 10/40 = 0,25 = 25%.\n2. No gráfico de setores, a fatia de futebol tem 25% de 360° = 0,25·360° = 90°.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (48, 8, 6, 'resumo', 'Resumo', '- Média = soma ÷ quantidade; na ponderada, cada valor conta conforme seu peso.\n- Mediana: sempre ordene os dados antes; com quantidade par, faça a média dos dois centrais.\n- Moda: o valor mais frequente.\n- Porcentagem de um setor × 360° = ângulo da fatia.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (49, 9, 1, 'explicacao', 'Dinheiro ao longo do tempo', 'A matemática financeira ajuda a decidir entre pagar à vista ou parcelado, entender descontos e saber quanto uma dívida ou investimento cresce.\n\n**Porcentagem** é uma fração com denominador 100: 15% = 15/100 = 0,15.\n\n**Juros** são o valor pago pelo uso de um dinheiro durante um tempo:\n- nos **juros simples**, os juros de cada período são sempre calculados sobre o valor inicial (capital);\n- nos **juros compostos**, os juros de cada período são somados ao saldo e passam a render juros também (\"juros sobre juros\").\n\nPor isso, com a mesma taxa, os juros compostos crescem mais rápido com o tempo. A maioria dos financiamentos, cartões de crédito e investimentos usa juros compostos.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (50, 9, 2, 'formulas', 'Conceitos e fórmulas', 'Notação: C = capital (valor inicial), i = taxa de juros na forma decimal, t = número de períodos, J = juros, M = montante (valor final).\n\n**Condição essencial:** a taxa e o tempo precisam estar na mesma unidade. Taxa ao mês → tempo em meses; taxa ao ano → tempo em anos.\n\n**Porcentagem**\n- p% de V = (p/100)·V.\n- Aumento de p%: V·(1 + p/100). Desconto de p%: V·(1 − p/100).\n- Aumentos e descontos sucessivos: multiplique os fatores (eles não se somam).\n\n**Juros simples**\n- J = C·i·t\n- M = C + J = C·(1 + i·t)\n\n**Juros compostos**\n- M = C·(1 + i)^{t}\n- J = M − C');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (51, 9, 3, 'exemplo', 'Exemplo 1 — Desconto à vista', 'Um celular custa R$ 1.200,00 e tem 15% de desconto no pagamento à vista. Qual é o preço à vista?\n\n1. Fator de desconto: 1 − 0,15 = 0,85.\n2. Preço: 1200·0,85 = 1020. O preço à vista é R$ 1.020,00 (economia de R$ 180,00).');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (52, 9, 4, 'exemplo', 'Exemplo 2 — Juros simples', 'R$ 2.000,00 são aplicados a juros simples de 1,5% ao mês durante 8 meses. Qual é o montante?\n\n1. Taxa e tempo estão em meses: i = 0,015 e t = 8.\n2. J = 2000·0,015·8 = 240.\n3. M = 2000 + 240 = 2240. O montante é R$ 2.240,00.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (53, 9, 5, 'exemplo', 'Exemplo 3 — Juros compostos × juros simples', 'R$ 1.000,00 são aplicados a 2% ao mês durante 3 meses. Compare juros compostos e simples.\n\n1. Compostos: M = 1000·(1,02)^{3} = 1000·1,061208 ≈ 1061,21. Montante de R$ 1.061,21.\n2. Simples: M = 1000·(1 + 0,02·3) = 1000·1,06 = 1060. Montante de R$ 1.060,00.\n3. Nos compostos, o montante é maior porque os juros de cada mês também rendem juros.');
INSERT INTO `topic_sections` (`id`, `topic_id`, `position`, `kind`, `title`, `body`) VALUES (54, 9, 6, 'resumo', 'Resumo', '- Transforme a porcentagem em decimal antes de calcular.\n- Aumento: multiplique por (1 + taxa); desconto: por (1 − taxa).\n- Simples: M = C·(1 + i·t). Compostos: M = C·(1 + i)^{t}.\n- Taxa e tempo sempre na mesma unidade.');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (1, 1, 'funcoes-01', 1, 'Qual é a raiz da função f(x) = 3x − 12?', 'A raiz é o valor de x que torna f(x) = 0: 3x − 12 = 0 → 3x = 12 → x = 4.', 'facil', 1, '7b59b9ab33e34962dc44d3544e24df11b6ab6dcb6349b54c8bb8f85ce4ba9a5f');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (2, 1, 'funcoes-02', 2, 'Uma locadora cobra R$ 40,00 fixos mais R$ 0,50 por quilômetro rodado. Qual função representa o valor V, em reais, para x quilômetros rodados?', 'O valor que muda com cada quilômetro (R$ 0,50) multiplica x, e o valor fixo (R$ 40,00) é somado: V(x) = 0,5x + 40.', 'facil', 1, '761597dfdef2afd8a355d25a9f4b0d29eb69055be5405b944edaad840f1121fa');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (3, 1, 'funcoes-03', 3, 'Quais são as raízes da equação x^{2} − 7x + 10 = 0?', 'Δ = (−7)^{2} − 4·1·10 = 49 − 40 = 9. Pela fórmula de Bhaskara, x = (7 ± 3) / 2, então x = 5 ou x = 2.', 'medio', 1, '38591d09710f41d363e577f1190cf3bc0c48e17c313d964d09b51274d15cee7b');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (4, 1, 'funcoes-04', 4, 'Qual é o vértice da parábola f(x) = −x^{2} + 4x + 1?', 'x_{v} = −b/(2a) = −4/(2·(−1)) = 2. Substituindo, f(2) = −4 + 8 + 1 = 5. Logo, V = (2, 5), que é ponto de máximo porque a = −1 < 0.', 'medio', 1, '653ad1cf91c4d6ec31ed7833bcd354a76084ac638f80bc4c3fbac2f30c594bab');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (5, 1, 'funcoes-05', 5, 'Para quais valores reais de k a equação x^{2} − 6x + k = 0 possui duas raízes reais diferentes?', 'É preciso Δ > 0: Δ = (−6)^{2} − 4·1·k = 36 − 4k. Então 36 − 4k > 0 → 4k < 36 → k < 9.', 'dificil', 1, 'ab33a83354d5120959a98bb0f1d9e7bdec36123bdbd4dc60520ccb46a6950e31');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (6, 2, 'progressoes-01', 1, 'Qual é o 10º termo da PA (4, 7, 10, ...)?', 'A razão é r = 7 − 4 = 3. Então a_{10} = 4 + (10 − 1)·3 = 4 + 27 = 31.', 'facil', 1, '4f0a2da0c558f69124490766129c6b62f0535f3142ee99c8854dbbc037364bb9');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (7, 2, 'progressoes-02', 2, 'Qual é a razão da PG (5, 15, 45, ...)?', 'Na PG, a razão é o quociente entre termos vizinhos: q = 15 / 5 = 3 (e 45 / 15 = 3).', 'facil', 1, '752dc4622b64cb646b013fa5cf860f88f88893f205156b623e55945e1b67c95e');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (8, 2, 'progressoes-03', 3, 'Um atleta corre 2 km no primeiro dia de treino e, a cada dia, corre 0,5 km a mais do que no dia anterior. Quantos quilômetros ele corre, no total, nos 10 primeiros dias?', 'É uma PA com a_{1} = 2 e r = 0,5. O 10º termo é a_{10} = 2 + 9·0,5 = 6,5. A soma é S_{10} = (2 + 6,5)·10 / 2 = 42,5 km.', 'medio', 1, '3374f682c1b6aa0ee407622f9331ae718a874d8d58d9c03a1557c1bf83bab3cb');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (9, 2, 'progressoes-04', 4, 'Em uma PG, o primeiro termo é 3 e a razão é 2. Qual é o 7º termo?', 'a_{7} = a_{1}·q^{6} = 3·2^{6} = 3·64 = 192.', 'medio', 1, 'cd89c5e20a22dbabd7dacbaadbbf2489bccfb6d91905d18cee1313ad9c782723');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (10, 2, 'progressoes-05', 5, 'Qual é a soma dos 6 primeiros termos da PG (1, 3, 9, ...)?', 'a_{1} = 1 e q = 3. S_{6} = 1·(3^{6} − 1)/(3 − 1) = (729 − 1)/2 = 364. Conferindo: 1 + 3 + 9 + 27 + 81 + 243 = 364.', 'dificil', 1, '2725d0195d3cbbcc34dfa85f8565372e0fe1bd9ed4735cc9818d02f752e6ac90');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (11, 3, 'exponencial-01', 1, 'Qual é o valor de x na equação 2^{x} = 64?', '64 = 2^{6}. Então 2^{x} = 2^{6} e, como as bases são iguais, x = 6.', 'facil', 1, '656e7ff0d4b393d4057f615cb4adeff601091ffb8c2a93c66f7db23ce541b402');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (12, 3, 'exponencial-02', 2, 'Quanto vale log_{3} 81?', 'Procuramos o expoente x tal que 3^{x} = 81. Como 3^{4} = 81, log_{3} 81 = 4.', 'facil', 1, '076bca6ad35a4afe3904a0a899b6a096b374b06b0703dba7fc5f0d6da5e149eb');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (13, 3, 'exponencial-03', 3, 'Qual é a solução da equação 5^{2x − 1} = 125?', '125 = 5^{3}. Então 2x − 1 = 3 → 2x = 4 → x = 2. Conferindo: 5^{2·2 − 1} = 5^{3} = 125.', 'medio', 1, '526581012aa23f08ea763614fc7b92d7d4565904f0b3d7fff384b553a9044ec8');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (14, 3, 'exponencial-04', 4, 'Considere log 2 ≈ 0,30 e log 3 ≈ 0,48. Qual é o valor aproximado de log 12?', '12 = 2^{2}·3. Pelas propriedades, log 12 = 2·log 2 + log 3 ≈ 2·0,30 + 0,48 = 1,08.', 'medio', 1, '378458f9c51a4ece3a917364e7565f24013ae1f22f815b2e13068dc1f1d42555');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (15, 3, 'exponencial-05', 5, 'Uma substância perde metade da sua massa a cada 3 horas. Partindo de 80 g, a massa após t horas é M(t) = 80·(1/2)^{t/3}. Depois de quanto tempo restarão 10 g?', '80·(1/2)^{t/3} = 10 → (1/2)^{t/3} = 1/8 = (1/2)^{3}. Igualando os expoentes, t/3 = 3 → t = 9 horas. (80 → 40 → 20 → 10: três períodos de 3 horas.)', 'dificil', 1, '8128784c259d93253cddbfc8ad458111e56d6eab78dbf18665b8f4b51583a676');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (16, 4, 'espacial-01', 1, 'Qual é o volume de um paralelepípedo com dimensões de 3 cm, 4 cm e 5 cm?', 'V = a·b·c = 3·4·5 = 60 cm^{3}.', 'facil', 1, 'd85f37043097aee091517054c597ca7b5e3e490a8a1816421c1761de95552428');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (17, 4, 'espacial-02', 2, 'Um cubo tem aresta de 4 cm. Qual é a sua área total?', 'O cubo tem 6 faces quadradas de área 4^{2} = 16 cm^{2}. Área total: 6·16 = 96 cm^{2}.', 'facil', 1, '452558037161ec04f6a77fe455371b238dfefb26e34387114c2e6061f2cd8243');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (18, 4, 'espacial-03', 3, 'Um copo cilíndrico tem raio interno de 3 cm e altura interna de 10 cm. Usando π ≈ 3,14, qual é a capacidade aproximada do copo, em mililitros?', 'V = πr^{2}h = π·9·10 = 90π cm^{3} ≈ 90·3,14 = 282,6 cm^{3}. Como 1 cm^{3} = 1 mL, a capacidade é de cerca de 282,6 mL.', 'medio', 1, 'ba0e29c1b2ecfb7d54588363479f8507d5b8b4be680ce345f3cc304186be1b25');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (19, 4, 'espacial-04', 4, 'Um cone reto tem raio da base de 6 cm e altura de 8 cm. Qual é o seu volume?', 'V = (1/3)·πr^{2}h = (1/3)·π·36·8 = (1/3)·288π = 96π cm^{3}. (288π seria o volume do cilindro de mesma base e altura.)', 'medio', 1, '8481b10fced3866d8f8b0d2db5829bc7868f8733376fcbfe14e24457560f9a0c');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (20, 4, 'espacial-05', 5, 'Uma esfera maciça de raio 3 cm é derretida, e todo o material é usado para formar um cilindro com raio da base de 3 cm. Qual é a altura desse cilindro?', 'O volume se mantém. Esfera: (4/3)·π·3^{3} = 36π cm^{3}. Cilindro: π·3^{2}·h = 9πh. Então 9πh = 36π → h = 4 cm.', 'dificil', 1, 'c0ce521d41514febb393f91a84232ca562670c56ec7086220717cd5c37b4c162');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (21, 5, 'trigonometria-01', 1, 'Qual é o valor de cos 60°?', 'cos 60° = 1/2 é um dos valores notáveis da trigonometria.', 'facil', 1, '7df6cb8b4055af9cfcc762fe45189e95fbbb88e212f993cf01064f1286de2887');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (22, 5, 'trigonometria-02', 2, 'Quanto mede um ângulo de 120° em radianos?', '120·π/180 = 120π/180 = 2π/3 rad.', 'facil', 1, '41a28f7642a23e90ab79feeee8f6f856cd3a416734a9d139bc4a0c0f3c1c8724');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (23, 5, 'trigonometria-03', 3, 'Uma escada de 10 m está apoiada em uma parede vertical e forma um ângulo de 60° com o chão horizontal. Usando √3 ≈ 1,73, a que altura aproximada ela toca a parede?', 'A altura é o cateto oposto ao ângulo de 60° e a escada é a hipotenusa: altura = 10·sen 60° = 10·√3/2 = 5√3 ≈ 5·1,73 = 8,65 m.', 'medio', 1, '64bea69f3e159be77043e16456cc6caf0088f2c2f88c277ad94ceb13dfb002c4');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (24, 5, 'trigonometria-04', 4, 'Os catetos de um triângulo retângulo medem 5 cm e 12 cm. Qual é o seno do ângulo oposto ao cateto de 5 cm?', 'Pela relação de Pitágoras, a hipotenusa mede √(25 + 144) = √169 = 13 cm. Então sen = oposto/hipotenusa = 5/13.', 'medio', 1, '4ee28025cffb9bf94d7f9fe19c556bbfc69bb34778d62a215117fc4e08300916');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (25, 5, 'trigonometria-05', 5, 'Sabendo que cos x = −0,6 e que x é um ângulo do 2º quadrante, qual é o valor de tg x?', 'sen^{2}x = 1 − 0,36 = 0,64, então sen x = ±0,8. No 2º quadrante o seno é positivo: sen x = 0,8. Logo, tg x = 0,8/(−0,6) = −4/3.', 'dificil', 1, 'fc95c7550e8a5740bc583e3b28ba3bf544e15f2a5346fa9adae4bb68a527a958');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (26, 6, 'combinatoria-01', 1, 'Uma lanchonete oferece 4 tipos de pão e 3 tipos de recheio. Quantos sanduíches diferentes, com um pão e um recheio, podem ser montados?', 'Pelo princípio multiplicativo: 4 opções de pão × 3 opções de recheio = 12 sanduíches.', 'facil', 1, 'df0a01071d1dc60a391b12807db6688e217c38bda731d72b804acfccbd4140c1');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (27, 6, 'combinatoria-02', 2, 'Uma urna tem 5 bolas vermelhas e 3 bolas azuis, todas iguais ao tato. Sorteando uma bola ao acaso, qual é a probabilidade de ela ser azul?', 'Há 8 bolas no total e 3 são azuis. P(azul) = 3/8.', 'facil', 1, 'dc23b56c1cd6e9cac016b04cc08a32dca94a27cf3d9c1aefec67d6cc29b3415f');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (28, 6, 'combinatoria-03', 3, 'Quantos anagramas tem a palavra BANANA?', 'São 6 letras com A repetido 3 vezes e N repetido 2 vezes: 6! / (3!·2!) = 720 / (6·2) = 60.', 'medio', 1, '9565468394dac26317cbd3bc04362c6976a0e90c3e30837353d10b57762e206e');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (29, 6, 'combinatoria-04', 4, 'Em uma turma de 8 alunos, quantas duplas diferentes podem ser formadas para um trabalho?', 'Na dupla, a ordem não importa: C_{8,2} = 8! / (2!·6!) = (8·7)/2 = 28. (56 contaria cada dupla duas vezes.)', 'medio', 1, 'd37838df5cc6aacf37dc966990632f6ce40f2cb414101257dea574102ca1abfd');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (30, 6, 'combinatoria-05', 5, 'Uma moeda honesta é lançada 3 vezes. Qual é a probabilidade de sair cara pelo menos uma vez?', 'Pelo complementar: a única forma de não sair cara é coroa nos 3 lançamentos, com probabilidade (1/2)^{3} = 1/8. Então P(pelo menos uma cara) = 1 − 1/8 = 7/8.', 'dificil', 1, '2f5c2bdfb61c5324f983935be812a82fa532a061749402bf5bdb67fa62f1c7bc');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (31, 7, 'analitica-01', 1, 'Qual é a distância entre os pontos A(1, 1) e B(4, 5)?', 'd = √((4 − 1)^{2} + (5 − 1)^{2}) = √(9 + 16) = √25 = 5.', 'facil', 1, '828b03ededf0bf9df2d0c01fda4ff40b41758c68e6e5ceb76cd92920bfa34004');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (32, 7, 'analitica-02', 2, 'Qual é o ponto médio do segmento com extremidades A(−2, 4) e B(6, 0)?', 'M = ((−2 + 6)/2, (4 + 0)/2) = (4/2, 4/2) = (2, 2).', 'facil', 1, '082661bac43114034242b1d3e6bc2ec2b4585687546639f840b3a3788814cddf');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (33, 7, 'analitica-03', 3, 'Qual é a equação reduzida da reta que passa pelos pontos (0, 3) e (2, 7)?', 'm = (7 − 3)/(2 − 0) = 2. A reta passa por (0, 3), então corta o eixo y em n = 3. Logo, y = 2x + 3. Conferindo: para x = 2, y = 7.', 'medio', 1, '29cd0f690ab39ef5f23c8d2e3e5ad2aee6b66e78b2fb13b0068c2d0d6134e976');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (34, 7, 'analitica-04', 4, 'Qual é o centro e o raio da circunferência (x + 1)^{2} + (y − 4)^{2} = 25?', 'Comparando com (x − a)^{2} + (y − b)^{2} = r^{2}: x + 1 = x − (−1), então a = −1; b = 4; r^{2} = 25, então r = 5.', 'medio', 1, '92b7f485f29a63089f14df0a498c0388c39819f293d4b69bdaeb19cff17c453b');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (35, 7, 'analitica-05', 5, 'Qual é o coeficiente angular de uma reta perpendicular à reta y = 3x − 2?', 'A reta dada tem m_{1} = 3. Para retas perpendiculares, m_{1}·m_{2} = −1, então m_{2} = −1/3.', 'dificil', 1, '7c338f1bb839154a8883d9f1d7fffc4c11ccf7af089480a485ddb6a530920bf9');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (36, 8, 'estatistica-01', 1, 'Qual é a média aritmética dos valores 12, 15, 18 e 15?', 'Soma: 12 + 15 + 18 + 15 = 60. Média: 60/4 = 15.', 'facil', 1, 'c14f7a36eb5af1c0fcb9bf6edb27cd86caaea2d7e8618f400eb7d561c95202c4');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (37, 8, 'estatistica-02', 2, 'Qual é a moda do conjunto de dados 3, 5, 5, 7, 8, 8, 8, 10?', 'O valor 8 aparece três vezes, mais do que qualquer outro. (6,75 é a média, não a moda.)', 'facil', 1, '39ba57e1e2ce4599736e081d90402edd880e9a0453320937a22fa650d2115d80');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (38, 8, 'estatistica-03', 3, 'Qual é a mediana dos valores 9, 2, 7, 4, 10 e 6?', 'Em ordem: 2, 4, 6, 7, 9, 10. São 6 valores (quantidade par), então a mediana é a média dos dois centrais: (6 + 7)/2 = 6,5.', 'medio', 1, 'cad77bb10369b68231e2de5d5ac4dd3c57edfff5d2917e9a7a2ebd0df262c054');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (39, 8, 'estatistica-04', 4, 'A nota final de uma disciplina é a média ponderada entre a prova (peso 3) e o trabalho (peso 2). Um aluno tirou 6,0 na prova e 8,5 no trabalho. Qual é a sua nota final?', '(6,0·3 + 8,5·2)/(3 + 2) = (18 + 17)/5 = 35/5 = 7,0. (7,25 seria a média simples, que ignora os pesos.)', 'medio', 1, '2f754e1e63ec69464d3ce0a4cdab53ae73dce8a54edf96c8a3484184594f1ff0');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (40, 8, 'estatistica-05', 5, 'A média de 5 números é 8. Ao retirar um desses números, a média dos 4 restantes passa a ser 7. Qual número foi retirado?', 'A soma dos 5 números é 5·8 = 40. A soma dos 4 restantes é 4·7 = 28. O número retirado é 40 − 28 = 12.', 'dificil', 1, 'b608b7136563bc906dfcb4cd6cf2a1e6fa5e1ca0635fc428067570388681b3f6');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (41, 9, 'financeira-01', 1, 'Quanto é 35% de R$ 240,00?', '35% de 240 = 0,35·240 = 84. Resposta: R$ 84,00. (R$ 156,00 é o que sobra após tirar 35%.)', 'facil', 1, 'd9067850938fc959ca71ff336bc9fde3e14286652c5ef90d1f69ff08604521a2');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (42, 9, 'financeira-02', 2, 'Uma conta de R$ 150,00 foi paga com atraso e teve acréscimo de 4%. Qual foi o valor pago?', 'Aumento de 4%: 150·1,04 = 156. O valor pago foi R$ 156,00.', 'facil', 1, '871f7476bd3eb16cc2dea7e8efab32b980b1c00e76ebef913f9681e37d98dd71');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (43, 9, 'financeira-03', 3, 'Um capital de R$ 800,00 foi aplicado a juros simples de 2% ao mês durante 6 meses. Qual é o montante ao final desse período?', 'J = C·i·t = 800·0,02·6 = 96. M = 800 + 96 = R$ 896,00. (R$ 96,00 são só os juros; R$ 900,93 seria o montante com juros compostos.)', 'medio', 1, '44de949222a4197e58238b708f52ad3ff34a3b99d4553da5634e0d1fa5399f07');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (44, 9, 'financeira-04', 4, 'Qual é o montante de R$ 5.000,00 aplicados a juros compostos de 10% ao ano durante 3 anos?', 'M = 5000·(1,10)^{3} = 5000·1,331 = 6655. O montante é R$ 6.655,00. (R$ 6.500,00 seria com juros simples.)', 'medio', 1, '88f30c9334be69c031e0684cb954378df8cbc872be88b6e9a39595734ee232ec');
INSERT INTO `questions` (`id`, `topic_id`, `code`, `position`, `statement`, `explanation`, `difficulty`, `active`, `content_hash`) VALUES (45, 9, 'financeira-05', 5, 'Um produto custava R$ 200,00. Ele teve um aumento de 25% e, depois, um desconto de 20% sobre o novo preço. Qual é o preço final?', 'Depois do aumento: 200·1,25 = 250. Depois do desconto: 250·0,80 = 200. Os fatores se multiplicam (1,25·0,80 = 1), então o preço final volta a R$ 200,00.', 'dificil', 1, '7ccacdbab600956ccd978fc089cdf0f164930fe7655d4a24cb581ada0a9bb12d');
